// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz: an arbitrary from address and a uint value; _tos length will be controlled via an array we build
    function testFuzz_property(address from, uint256 v) public {
        // Keep wide domain
        vm.assume(from != address(0));

        // Deploy a helper that will revert when its transferFrom is invoked
        Reverter reverter = new Reverter();

        // Build a single-element tos array to ensure exactly one external call is made
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead); // arbitrary recipient inside the callee; irrelevant to c

        // Call and observe whether c.transfer reverts or not. The reference implementation should revert
        // because the callee (reverter) will revert on the low-level call; the mutant that swallows failures
        // will not revert and will return true, so this property distinguishes them.
        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for all inputs, the correct C reverts (ok == false). The mutant that ignores failures
        // will make ok == true for some inputs (here any inputs) when callee reverts. Assert that call did revert.
        assertTrue(!ok);
    }
}

// Adversarial helper that reverts when called with the selector transferFrom(address,address,uint256)
contract Reverter {
    // Declare the exact function so ABI decoding matches what C encodes
    function transferFrom(address, address, uint256) external pure {
        revert("revert-from-helper");
    }
}
